<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../lib/ManagementReportsRepository.php';Auth::requireLogin();
try{$attachment=Database::fetch('SELECT a.*,s.report_type,s.submitter_id,s.status FROM management_report_attachments a JOIN management_report_submissions s ON s.id=a.submission_id WHERE a.id=?',[(int)($_GET['id']??0)]);if(!$attachment||!ManagementReportsRepository::canView($attachment))throw new RuntimeException('not_found');$root=realpath(__DIR__.'/..');$base=realpath($root.'/uploads/management-reports');$path=realpath($root.'/'.ltrim($attachment['storage_path'],'/'));if(!$base||!$path||!str_starts_with(strtolower($path),strtolower($base.DIRECTORY_SEPARATOR))||!is_file($path))throw new RuntimeException('not_found');Auth::log((int)Auth::user()['id'],'management_report_attachment_downloaded','management_report_attachments',(int)$attachment['id']);header('Content-Type: '.($attachment['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($attachment['original_name']));header('X-Content-Type-Options: nosniff');readfile($path);exit;}catch(Throwable $e){error_log('Management report attachment: '.$e->getMessage());http_response_code(404);exit('فایل در دسترس نیست.');}
